fn apply_animation_evaluation(
    source: Entity,
    timeline: &CompiledTimeline,
    evaluation: &TimelineEvaluation,
    player_state: TimelinePlayState,
    player_rate: f32,
    force_seek: bool,
    world: &mut World,
    bindings: &TimelineBindings,
    diagnostics: &mut TimelineDiagnostics,
) {
    release_inactive_animation_overrides(source, timeline, evaluation, world, bindings);

    for active in &evaluation.active {
        let TimelineTrackOutput::Animation {
            entity,
            motion_slot,
            speed,
            looping,
        } = &active.output
        else {
            continue;
        };
        let Some(authoring) = entity else {
            continue;
        };
        let Some(target) = bindings.resolve(authoring) else {
            diagnostics.push(TimelineBindingDiagnostic::UnresolvedEntity {
                authoring: authoring.as_stable_id().as_str().to_owned(),
            });
            continue;
        };
        let Some(track) = timeline.track(&active.track) else {
            continue;
        };
        let Some(animation_set) = track.asset.as_ref() else {
            continue;
        };

        let Some(graph_player) = world.get_component::<AnimGraphPlayer>(target) else {
            diagnostics.push(TimelineBindingDiagnostic::MissingComponent {
                authoring: authoring.as_stable_id().as_str().to_owned(),
                component: "AnimGraphPlayer",
            });
            continue;
        };
        let actual_set = graph_player
            .debug_source()
            .map(|source| source.animation_set_asset.clone());
        if actual_set.as_ref() != Some(animation_set) {
            diagnostics.push(TimelineBindingDiagnostic::AnimationSetMismatch {
                authoring: authoring.as_stable_id().as_str().to_owned(),
                expected: animation_set.clone(),
                actual: actual_set,
            });
            continue;
        }
        let Some(clip) = graph_player.clip_handle(motion_slot.as_str()) else {
            diagnostics.push(TimelineBindingDiagnostic::UnresolvedMotionSlot {
                authoring: authoring.as_stable_id().as_str().to_owned(),
                animation_set: animation_set.clone(),
                motion_slot: motion_slot.clone(),
            });
            continue;
        };

        let acquired = world
            .get_component_mut::<AnimGraphPlayer>(target)
            .is_some_and(|player| player.acquire_external_override(source));
        if !acquired {
            diagnostics.push(TimelineBindingDiagnostic::AnimationOverrideConflict {
                authoring: authoring.as_stable_id().as_str().to_owned(),
            });
            continue;
        }

        let Some(animator) = world.get_component_mut::<Animator>(target) else {
            if let Some(player) = world.get_component_mut::<AnimGraphPlayer>(target) {
                player.release_external_override(source);
            }
            diagnostics.push(TimelineBindingDiagnostic::MissingComponent {
                authoring: authoring.as_stable_id().as_str().to_owned(),
                component: "Animator",
            });
            continue;
        };
        let playback_speed = *speed * player_rate;
        if !animator.set_playback_speed(playback_speed) {
            if let Some(player) = world.get_component_mut::<AnimGraphPlayer>(target) {
                player.release_external_override(source);
            }
            diagnostics.push(TimelineBindingDiagnostic::InvalidAnimationPlaybackRate {
                authoring: authoring.as_stable_id().as_str().to_owned(),
            });
            continue;
        }
        let entered = evaluation
            .entered
            .iter()
            .any(|transition| transition.track == active.track && transition.clip == active.clip);
        let clip_changed = animator.clip != clip;
        animator.clip = clip;
        animator.set_looping(*looping);
        if force_seek || entered || clip_changed {
            let seconds = active.offset as f64
                / CompiledTimeline::ticks_per_second() as f64
                * f64::from(*speed);
            animator.seek(seconds as f32);
        }
        match player_state {
            TimelinePlayState::Playing => animator.play(),
            TimelinePlayState::Paused => animator.pause(),
            TimelinePlayState::Stopped => animator.stop(),
        }
    }
}

fn release_inactive_animation_overrides(
    source: Entity,
    timeline: &CompiledTimeline,
    evaluation: &TimelineEvaluation,
    world: &mut World,
    bindings: &TimelineBindings,
) {
    for track in &timeline.tracks {
        if !track.enabled || track.kind != TimelineTrackKind::Animation {
            continue;
        }
        let is_active = evaluation.active.iter().any(|active| {
            active.track == track.id
                && matches!(active.output, TimelineTrackOutput::Animation { .. })
        });
        if is_active {
            continue;
        }
        let Some(authoring) = track.entity.as_ref() else {
            continue;
        };
        let Some(target) = bindings.resolve(authoring) else {
            continue;
        };
        if let Some(player) = world.get_component_mut::<AnimGraphPlayer>(target) {
            player.release_external_override(source);
        }
    }
}

